package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.nio.file.FileSystems;
import java.nio.file.attribute.BasicFileAttributes;
import org.junit.jupiter.api.Test;

class Bzip2BasicFileAttributeViewMutaGate2Test {

  private static final class Outcome {
    final BasicFileAttributes attrs;
    final Class<?> failure;

    Outcome(BasicFileAttributes attrs, Class<?> failure) {
      this.attrs = attrs;
      this.failure = failure;
    }
  }

  private interface Call {
    BasicFileAttributes run() throws Exception;
  }

  private static Outcome capture(Call call) {
    try {
      return new Outcome(call.run(), null);
    } catch (Throwable t) {
      return new Outcome(null, t.getClass());
    }
  }

  @Test
  void readAttributesDelegatesToSupport() {
    SingleEntryArchiveFormat[] formats = SingleEntryArchiveFormat.class.getEnumConstants();
    SingleEntryArchiveFormat format = formats == null || formats.length == 0 ? null : formats[0];
    SingleEntryArchivePath path =
        new SingleEntryArchivePath(FileSystems.getDefault(), format, true, "entry.txt");
    Bzip2BasicFileAttributeView view = new Bzip2BasicFileAttributeView(path);

    Outcome expected = capture(() -> CompressorArchiveProviderSupport.readBasicAttributes(path));
    Outcome actual = capture(view::readAttributes);

    assertEquals(expected.failure, actual.failure);
    if (expected.failure == null) {
      assertNotNull(actual.attrs);
      assertEquals(expected.attrs.size(), actual.attrs.size());
      assertEquals(expected.attrs.isDirectory(), actual.attrs.isDirectory());
      assertEquals(expected.attrs.isRegularFile(), actual.attrs.isRegularFile());
      assertEquals(expected.attrs.isSymbolicLink(), actual.attrs.isSymbolicLink());
      assertEquals(expected.attrs.isOther(), actual.attrs.isOther());
    }
  }
}

